  assign m_where[30] = astate == 6'd30 && P == 8'd34 && P2 == 8'd35;
  assign m_gap[30] = since >= 5'd16 && since <= 5'd16;
`ifdef SLOTS
  assign m_slot[30] = slot >= 9'd466 && slot <= 9'd466;
`endif
  // levels: the pins the line writes at its level (not the data pin of a line with data), the
  // other channel pins unchanged
  wire [30:0] m_level, m_data, m_sub;
  assign m_level[0] = vis_a[1:0] == 2'b11;
  assign m_data[0] = 1'b1;
  assign m_sub[0] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[1] = vis_a[1:0] == 2'b10;
  assign m_data[1] = 1'b1;
  assign m_sub[1] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[2] = 1'b1;
  assign m_data[2] = vis_a[1:0] == {1'b1, byte0[0]};  // byte0.bit0, push-pull
  assign m_sub[2] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[3] = 1'b1;
  assign m_data[3] = vis_a[1:0] == {1'b1, byte0[1]};  // byte0.bit1, push-pull
  assign m_sub[3] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[4] = 1'b1;
  assign m_data[4] = vis_a[1:0] == {1'b1, byte0[2]};  // byte0.bit2, push-pull
  assign m_sub[4] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[5] = 1'b1;
  assign m_data[5] = vis_a[1:0] == {1'b1, byte0[3]};  // byte0.bit3, push-pull
  assign m_sub[5] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[6] = 1'b1;
  assign m_data[6] = vis_a[1:0] == {1'b1, byte0[4]};  // byte0.bit4, push-pull
  assign m_sub[6] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[7] = 1'b1;
  assign m_data[7] = vis_a[1:0] == {1'b1, byte0[5]};  // byte0.bit5, push-pull
  assign m_sub[7] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[8] = 1'b1;
  assign m_data[8] = vis_a[1:0] == {1'b1, byte0[6]};  // byte0.bit6, push-pull
  assign m_sub[8] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[9] = 1'b1;
  assign m_data[9] = vis_a[1:0] == {1'b1, byte0[7]};  // byte0.bit7, push-pull
  assign m_sub[9] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[10] = vis_a[1:0] == 2'b11;
  assign m_data[10] = 1'b1;
  assign m_sub[10] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[11] = vis_a[1:0] == 2'b10;
  assign m_data[11] = 1'b1;
  assign m_sub[11] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[12] = 1'b1;
  assign m_data[12] = vis_a[1:0] == {1'b1, byte1[0]};  // byte1.bit0, push-pull
  assign m_sub[12] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[13] = 1'b1;
  assign m_data[13] = vis_a[1:0] == {1'b1, byte1[1]};  // byte1.bit1, push-pull
  assign m_sub[13] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[14] = 1'b1;
  assign m_data[14] = vis_a[1:0] == {1'b1, byte1[2]};  // byte1.bit2, push-pull
  assign m_sub[14] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[15] = 1'b1;
  assign m_data[15] = vis_a[1:0] == {1'b1, byte1[3]};  // byte1.bit3, push-pull
  assign m_sub[15] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[16] = 1'b1;
  assign m_data[16] = vis_a[1:0] == {1'b1, byte1[4]};  // byte1.bit4, push-pull
  assign m_sub[16] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[17] = 1'b1;
  assign m_data[17] = vis_a[1:0] == {1'b1, byte1[5]};  // byte1.bit5, push-pull
  assign m_sub[17] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[18] = 1'b1;
  assign m_data[18] = vis_a[1:0] == {1'b1, byte1[6]};  // byte1.bit6, push-pull
  assign m_sub[18] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[19] = 1'b1;
  assign m_data[19] = vis_a[1:0] == {1'b1, byte1[7]};  // byte1.bit7, push-pull
  assign m_sub[19] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[20] = vis_a[1:0] == 2'b11;
  assign m_data[20] = 1'b1;
  assign m_sub[20] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[21] = vis_a[1:0] == 2'b10;
  assign m_data[21] = 1'b1;
  assign m_sub[21] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[22] = 1'b1;
  assign m_data[22] = vis_a[1:0] == {1'b1, byte2[0]};  // byte2.bit0, push-pull
  assign m_sub[22] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[23] = 1'b1;
  assign m_data[23] = vis_a[1:0] == {1'b1, byte2[1]};  // byte2.bit1, push-pull
  assign m_sub[23] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[24] = 1'b1;
  assign m_data[24] = vis_a[1:0] == {1'b1, byte2[2]};  // byte2.bit2, push-pull
  assign m_sub[24] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[25] = 1'b1;
  assign m_data[25] = vis_a[1:0] == {1'b1, byte2[3]};  // byte2.bit3, push-pull
  assign m_sub[25] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[26] = 1'b1;
  assign m_data[26] = vis_a[1:0] == {1'b1, byte2[4]};  // byte2.bit4, push-pull
  assign m_sub[26] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[27] = 1'b1;
  assign m_data[27] = vis_a[1:0] == {1'b1, byte2[5]};  // byte2.bit5, push-pull
  assign m_sub[27] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[28] = 1'b1;
  assign m_data[28] = vis_a[1:0] == {1'b1, byte2[6]};  // byte2.bit6, push-pull
  assign m_sub[28] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[29] = 1'b1;
  assign m_data[29] = vis_a[1:0] == {1'b1, byte2[7]};  // byte2.bit7, push-pull
  assign m_sub[29] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  assign m_level[30] = vis_a[1:0] == 2'b11;
  assign m_data[30] = 1'b1;
  assign m_sub[30] = sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0];
  reg [4:0] deadline; reg has_deadline;
  always @(*) begin
    has_deadline = 1'b1;
    case (astate)
      6'd0: deadline = 5'd16;
      6'd1: deadline = 5'd16;
      6'd2: deadline = 5'd16;
      6'd3: deadline = 5'd16;
      6'd4: deadline = 5'd16;
      6'd5: deadline = 5'd16;
      6'd6: deadline = 5'd16;
      6'd7: deadline = 5'd16;
      6'd8: deadline = 5'd16;
      6'd9: deadline = 5'd16;
      6'd10: deadline = 5'd16;
      6'd11: deadline = 5'd16;
      6'd12: deadline = 5'd16;
      6'd13: deadline = 5'd16;
      6'd14: deadline = 5'd16;
      6'd15: deadline = 5'd16;
      6'd16: deadline = 5'd16;
      6'd17: deadline = 5'd16;
      6'd18: deadline = 5'd16;
      6'd19: deadline = 5'd16;
      6'd20: deadline = 5'd16;
      6'd21: deadline = 5'd16;
      6'd22: deadline = 5'd16;
      6'd23: deadline = 5'd16;
      6'd24: deadline = 5'd16;
      6'd25: deadline = 5'd16;
      6'd26: deadline = 5'd16;
      6'd27: deadline = 5'd16;
      6'd28: deadline = 5'd16;
      6'd29: deadline = 5'd16;
      6'd30: deadline = 5'd16;
      default: begin deadline = 5'd0; has_deadline = 1'b0; end
    endcase
  end
  reg [5:0] next_state;
  always @(*) begin
    next_state = astate;
    if (m_where[0]) next_state = 6'd1;
    if (m_where[1]) next_state = 6'd2;
    if (m_where[2]) next_state = 6'd3;
    if (m_where[3]) next_state = 6'd4;
    if (m_where[4]) next_state = 6'd5;
    if (m_where[5]) next_state = 6'd6;
    if (m_where[6]) next_state = 6'd7;
    if (m_where[7]) next_state = 6'd8;
    if (m_where[8]) next_state = 6'd9;
    if (m_where[9]) next_state = 6'd10;
    if (m_where[10]) next_state = 6'd11;
    if (m_where[11]) next_state = 6'd12;
    if (m_where[12]) next_state = 6'd13;
    if (m_where[13]) next_state = 6'd14;
    if (m_where[14]) next_state = 6'd15;
    if (m_where[15]) next_state = 6'd16;
    if (m_where[16]) next_state = 6'd17;
    if (m_where[17]) next_state = 6'd18;
    if (m_where[18]) next_state = 6'd19;
    if (m_where[19]) next_state = 6'd20;
    if (m_where[20]) next_state = 6'd21;
    if (m_where[21]) next_state = 6'd22;
    if (m_where[22]) next_state = 6'd23;
    if (m_where[23]) next_state = 6'd24;
    if (m_where[24]) next_state = 6'd25;
    if (m_where[25]) next_state = 6'd26;
    if (m_where[26]) next_state = 6'd27;
    if (m_where[27]) next_state = 6'd28;
    if (m_where[28]) next_state = 6'd29;
    if (m_where[29]) next_state = 6'd30;
    if (m_where[30]) next_state = 6'd31;
  end
  always @(posedge clock) if (step) begin
    if (event_) begin astate <= next_state; since <= 5'd1; end
    else if (since != 5'd18) since <= since + 5'd1;
`ifdef SLOTS
    if (slot != 9'd468) slot <= slot + 9'd1;
`endif
    if (event_ && next_state == 6'd31) done <= 1'b1;
    if (event_ && next_state == 6'd31) fin_31 <= 1'b1;
  end
  // ---- properties ----
  always @(*) if (step) begin
    events: assert (!event_ || (m_where & m_gap) != 31'd0);
    levels: assert (event_ ? (m_where & m_level) != 31'd0 : (vis_a & VCH) == (vis_b & VCH));
    data: assert (!event_ || (m_where & m_data) != 31'd0);
    subslot: assert (event_ ? (m_where & m_sub) != 31'd0 : (sub_a[0] == out_a[0] && sub_a[1] == out_a[0] && sub_a[2] == out_a[0] && sub_a[3] == out_a[0]));
    deadline_: assert (!has_deadline || since <= deadline);
  end
  always @(*) if (past1 && phase != 2'd1) quiet: assert ((vis & VCH) == (vis_prev & VCH) && pin_sub[0] == pin_out[0] && pin_sub[1] == pin_out[0] && pin_sub[2] == pin_out[0] && pin_sub[3] == pin_out[0]);
  always @(*) if (fetch_t && started) page: assert (imem_addr[9:8] == T);
`ifdef SLOTS
  always @(*) if (step) slots: assert (!event_ || (m_where & m_slot) != 31'd0);
  always @(*) slots_ante: cover (done);
`endif
  // antecedents: the certificate's last state (state 31) is reached
  always @(*) events_ante: cover (done);
  always @(*) levels_ante: cover (done);
  always @(*) data_ante: cover (done);
  always @(*) subslot_ante: cover (done);
  always @(*) deadline__ante: cover (done);
  always @(*) quiet_ante: cover (done);
  always @(*) page_ante: cover (done);
  always @(*) final_31: cover (fin_31);
  // the same as one negated assertion, for a bit-level BMC (abc bmc3): failing at step n is
  // reachable at step n. REACH names the signal (done, or fin_N)
`ifdef REACH
  always @(*) reach: assert (!`REACH);
`endif
endmodule
